create extension if not exists pgcrypto;
do $$ begin create type user_role as enum ('customer','admin','super_admin'); exception when duplicate_object then null; end $$;
create table if not exists users(id uuid primary key default gen_random_uuid(), name text not null, shop_name text, phone text unique not null, password_hash text not null, address text, area text, pincode text, role user_role not null default 'customer', fcm_token text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(), slug text unique not null, name_en text not null, name_hi text, image_url text, tint text, sort_order int default 0, is_active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists brands(id uuid primary key default gen_random_uuid(), name text unique not null, logo_url text, is_active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(), sku text unique, category_id uuid references categories(id), brand text, name_en text not null, name_hi text, size text, pack text, image_url text, mrp numeric(10,2) not null default 0, buy_price numeric(10,2) not null default 0, stock int not null default 0, regional boolean default false, high_margin boolean default false, trending_areas text[], is_active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists product_variants(id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, size text not null, pack text, mrp numeric(10,2), buy_price numeric(10,2), created_at timestamptz default now());
create table if not exists offers(id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_url text, media_type text default 'image', product_id uuid references products(id), discount_percent int, link_url text, is_active boolean default true, starts_at timestamptz, ends_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists addresses(id uuid primary key default gen_random_uuid(), user_id uuid references users(id) on delete cascade, name text, phone text, line1 text not null, area text, city text, state text, pincode text, is_default boolean default false, created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(), user_id uuid references users(id), address_id uuid references addresses(id), status text not null default 'pending', total numeric(10,2) not null default 0, items jsonb not null default '[]', notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(), order_id uuid references orders(id) on delete cascade, product_id uuid references products(id), quantity int not null, mrp numeric(10,2), buy_price numeric(10,2));
create table if not exists payments(id uuid primary key default gen_random_uuid(), order_id uuid references orders(id), mode text not null, status text not null default 'pending', amount numeric(10,2) not null, provider_ref text, created_at timestamptz default now());
create table if not exists inventory(id uuid primary key default gen_random_uuid(), product_id uuid references products(id), quantity int not null default 0, reserved_quantity int not null default 0, updated_at timestamptz default now());
create index if not exists idx_products_category on products(category_id); create index if not exists idx_orders_user on orders(user_id);
